package org.pocketlore.app;
import android.app.*;import android.content.*;import android.os.*;import android.system.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import org.json.*;
/** Existing resident model only; no generation call, corpus provisioning or service changes. */
public final class ModernIntegratedInstrumentation extends Instrumentation {
 String id;Bundle invocation;File dir;Activity activity;JSONObject report=new JSONObject();JSONArray checks=new JSONArray();long session;
 void ok(boolean b,String s){if(!b)throw new AssertionError(s);checks.put(s);}
 public void onCreate(Bundle b){super.onCreate(b);invocation=b;id=b.getString("run_id");start();}
 interface Ready{boolean get();}void await(Ready r)throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(!r.get()&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);ok(r.get(),"Activity ready");}
 View find(View v,String label){if(v instanceof TextView&&label.equals(((TextView)v).getText().toString()))return v;if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++){View x=find(((android.view.ViewGroup)v).getChildAt(i),label);if(x!=null)return x;}return null;}
 void image(String name)throws Exception{waitForIdleSync();Thread.sleep(400);Bitmap b=getUiAutomation().takeScreenshot();ok(b!=null,"Screenshot "+name);try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();getUiAutomation().getRootInActiveWindow();}
 void close(){if(activity!=null){runOnMainSync(activity::finish);waitForIdleSync();activity=null;}}
 public void onStart(){Bundle result=new Bundle();try{
  dir=new File(getTargetContext().getFilesDir(),"modern-"+id);dir.mkdirs();report.put("run_id",id).put("sdk",Build.VERSION.SDK_INT).put("page_size",Os.sysconf(OsConstants._SC_PAGESIZE)).put("fingerprint",Build.FINGERPRINT).put("generation_performed",false);
  ok(Build.VERSION.SDK_INT==37&&Os.sysconf(OsConstants._SC_PAGESIZE)==16384,"Actual API37 16KB process");report.put("runtime",NativeRuntime.identity()).put("index_runtime",NativeIndex.identity());
  File model=new File(getTargetContext().getFilesDir(),"page-size-test/model.gguf");ok(model.isFile(),"Resident task305 model available");String hash=BroadPack.hash(model);ok(hash.equals("74a4da8c9fdbcd15bd1f6d01d621410d31c6fc00986f5eb687824e7b93d7a9db"),"Resident model pin");report.put("model_sha256",hash).put("model_bytes",model.length());
  session=NativeRuntime.create();NativeRuntime.cancel(session);boolean denied=false;try{NativeRuntime.load(session,model.getPath().getBytes(StandardCharsets.UTF_8));}catch(Exception expected){denied=true;report.put("cancelled_load",expected.toString());}ok(denied,"Precancelled load rejected");NativeRuntime.reset(session);
  long start=System.nanoTime();NativeRuntime.load(session,model.getPath().getBytes(StandardCharsets.UTF_8));report.put("load_ms",(System.nanoTime()-start)/1e6);Debug.MemoryInfo loaded=new Debug.MemoryInfo();Debug.getMemoryInfo(loaded);report.put("loaded_pss_kib",loaded.getTotalPss()).put("loaded_native_heap_bytes",Debug.getNativeHeapAllocatedSize());ok(NativeRuntime.resourceState()[1]==0,"Load has no generation context");NativeRuntime.cancel(session);NativeRuntime.reset(session);NativeRuntime.close(session);session=NativeRuntime.create();start=System.nanoTime();NativeRuntime.load(session,model.getPath().getBytes(StandardCharsets.UTF_8));report.put("reload_ms",(System.nanoTime()-start)/1e6);NativeRuntime.close(session);session=0;ok(NativeRuntime.resourceState()[0]==0&&NativeRuntime.resourceState()[1]==0,"Cancel reset close reload releases native state");
  JSONObject payload=ReviewedCities.load(getTargetContext());JSONArray cards=payload.getJSONArray("cards"),exports=new JSONArray();
  boolean rejected=false;try{ReviewedCities.parse((payload.toString()+" ").getBytes(StandardCharsets.UTF_8));}catch(Exception e){rejected=true;}ok(rejected,"Changed reviewed payload rejected");
  for(int i=0;i<cards.length();i++){JSONObject card=cards.getJSONObject(i);ok(card.getJSONArray("fields").length()==6,"Only six reviewed fields");String body=ReviewedCities.render(payload,card,-1);ok(body.contains("not generated reasoning")&&body.contains("Section 8")&&body.contains("agency: unknown"),"Rights date and extractive limitations visible");for(int f=0;f<6;f++){JSONObject field=card.getJSONArray("fields").getJSONObject(f);ok(body.contains(field.getString("quote"))&&body.contains("["+field.getInt("start_utf16")+", "+field.getInt("end_utf16")+")"),"Exact reviewed field and offsets");}
   long record;try(NotebookStore store=new NotebookStore(getTargetContext())){record=store.add("source","Reviewed city "+card.getString("id"),"",body,card.getString("notice"),false);}
   activity=startActivitySync(new Intent(getTargetContext(),SourceReaderActivity.class).putExtra("record",record).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));SourceReaderActivity reader=(SourceReaderActivity)activity;await(()->reader.content!=null);ok(reader.entry.body.equals(body),"Actual reader retains approved projection");String exported=reader.entry.portable();ok(exported.contains(body)&&!exported.contains("alternatenames:"),"Portable export retains projection only");Files.write(new File(dir,"city-"+card.getString("id")+".md").toPath(),exported.getBytes(StandardCharsets.UTF_8));android.net.Uri destination=android.net.Uri.parse("content://org.pocketlore.fixture.notebook/success");File portableFile=new File(dir,"city-"+card.getString("id")+".md");runOnMainSync(()->reader.writeDocument(portableFile,destination));await(()->reader.exportJob==null);ok(reader.operation.getText().toString().startsWith("Notebook exported"),"Actual reviewed card provider export completes");try(InputStream in=getTargetContext().getContentResolver().openInputStream(destination)){ok(java.util.Arrays.equals(in.readAllBytes(),exported.getBytes(StandardCharsets.UTF_8)),"Actual provider card export matches exact reviewed bytes");}exports.put(new JSONObject().put("id",card.getString("id")).put("sha256",ReviewedCities.hash(exported)));image("city-"+card.getString("id"));close();
  }report.put("reviewed_cards",exports).put("city_index","absent; reviewed projection/reader only, not nearby venue lookup");
  File root=getTargetContext().getFilesDir();boolean ocr=AttachmentAssets.available(root,false),speech=AttachmentAssets.available(root,true);report.put("ocr_asset_present",ocr).put("speech_asset_present",speech);ok(!ocr&&!speech,"Observed optional assets absent on subset emulator");
  activity=startActivitySync(new Intent(getTargetContext(),AttachmentsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(()->find(activity.getWindow().getDecorView(),"Record speech").performClick());ok(find(activity.getWindow().getDecorView(),"Local speech model absent. Typing remains available; no microphone started.")!=null,"Missing speech does not start microphone");image("recognition-absent");runOnMainSync(()->find(activity.getWindow().getDecorView(),"Cancel recognition").performClick());ok(find(activity.getWindow().getDecorView(),"Cancelled. No recognized input will be submitted.")!=null,"Recognition cancellation clears input");close();
  boolean absent=false;try{AttachmentEngine.image(root,new byte[]{1},"public absent-engine control",()->false);}catch(IOException e){absent=e.getMessage().contains("absent");}ok(absent,"Missing OCR fails explicitly before image recognition");
  Debug.MemoryInfo mem=new Debug.MemoryInfo();Debug.getMemoryInfo(mem);report.put("final_pss_kib",mem.getTotalPss()).put("status","PASS");
 }catch(Throwable t){try{report.put("status","FAIL").put("error",android.util.Log.getStackTraceString(t));}catch(Exception ignored){}}
 finally{if(session!=0)NativeRuntime.close(session);close();try{report.put("checks",checks);Files.write(new File(dir,"report.json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));DeviceEvidence.emit(this,invocation,dir);result.putString("stream",report.toString());}catch(Exception e){result.putString("stream",e.toString());}finish(report.optString("status").equals("PASS")?-1:1,result);}
 }
}
